return '<div class="jev-recommendations"><h4>'+product('Jev 추천 · 한 곳')+'</h4>'+suggestions.map(item=>'<article class="jev-recommendation">'+field('단계',item.step_goal||item.step_id)+'<p><b>'+raw(item.judgment)+'</b> · '+product(shape[item.answer_shape]||'짧은 판단')+'</p>'+field('이곳을 선정한 이유',item.why_selected||item.why_fit)+field('기대 효과',item.expected_gain,'효율 개선 여부는 아직 측정하지 않았습니다.')+'<details><summary>'+product('코드 근거와 판단 방식')+'</summary>'+field('Jev가 맞는 이유',item.why_fit)+field('현재 처리',item.baseline)+field('반복 근거',item.repetition_basis)+field('필요한 입력',(item.state_inputs||[]).map(input=>input.name).join(', '))+field('불확실할 때',item.fallback,'기존 LLM 경로 유지')+field('근거',(item.evidence||[]).map(ref=>ref.file+':'+ref.line).join(', '),'위치 미확인')+'</details></article>').join('')+'<p class="muted">코드 분석에 따른 예상이며 실제 개선 폭은 측정하지 않았습니다. Jev를 켜도 원본 코드는 바뀌지 않습니다.</p></div>';
