async function loadCodingSessions(){if(codingBusy||!detail?.coding_attach?.eligible)return;const project=document.getElementById('coding-project-ref')?.value.trim()||'';if(!project){setMessage('등록된 프로젝트 이름을 입력해 주세요.');return}codingBusy=true;attachProjectRef=project;attachSessionId='';attachRequestId=null;codingCatalog=null;codingCatalogProject='';setMessage('이 프로젝트의 Codex 세션을 확인하는 중…');try{const response=await fetch('work/coding/sessions?project_ref='+encodeURIComponent(project),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'Codex 세션을 읽지 못했습니다.');codingCatalog=data;codingCatalogProject=project;renderDetail();setMessage('연결할 기존 세션을 직접 선택해 주세요. 같은 세션을 다른 Codex 창에서 동시에 사용하지 마세요.')}catch(error){renderDetail();setMessage(String(error.message||error))}finally{codingBusy=false}}
