// An action that calls the AI takes about a minute. It says so at once and counts the seconds, so a wait never looks
// like a press that did nothing.
let waitingTimer=null;
function waiting(ko,en){clearInterval(waitingTimer);const started=Date.now(),paint=()=>setMessage(window.officeCopy(ko,en)+' · '+Math.round((Date.now()-started)/1000)+(document.documentElement.lang==='en'?' s':'초'));paint();waitingTimer=setInterval(paint,1000);window.officeBusy?.(true);}
