let intakeDefaults=null,intakeDefault=null,intakeCatalogs=null,intakeTouched=false;const intakeEfforts={codex:['low','medium','high','xhigh'],claude:['low','medium','high','xhigh','max']};
function fillIntakeClient(reset){const client=document.getElementById('work-client').value,model=document.getElementById('work-model'),effort=document.getElementById('work-effort');
// No client means the owner's own default app runs it (an OpenCode default keeps the host's loop): nothing to choose under it.
model.disabled=effort.disabled=!client;if(!client){model.innerHTML=effort.innerHTML='<option value="">'+esc(window.officeText('앱 기본값'))+'</option>';return;}
const fixed=intakeDefault&&intakeDefault.id===client?intakeDefault:null,models=intakeCatalogs?.[client]?.models||[],want=(!reset&&model.value)||(fixed?fixed.model:intakeDefaults?.client_models?.[client])||'',wantEffort=(!reset&&effort.value)||(fixed?fixed.effort:client==='codex'?intakeDefaults?.codex_reasoning_effort:'')||'',efforts=[...intakeEfforts[client],...(wantEffort&&!intakeEfforts[client].includes(wantEffort)?[wantEffort]:[])],fallback=window.officeText('앱 기본값');
model.innerHTML='<option value="">'+esc(fallback)+'</option>'+models.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.label||m.id)+'</option>').join('')+(want&&!models.some(m=>m.id===want)?'<option value="'+esc(want)+'">'+esc(want)+'</option>':'');model.value=want;
effort.innerHTML='<option value="">'+esc(fallback)+'</option>'+efforts.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');effort.value=wantEffort;}
document.getElementById('work-client').onchange=()=>{intakeTouched=true;fillIntakeClient(true);};document.getElementById('work-model').onchange=document.getElementById('work-effort').onchange=()=>{intakeTouched=true;};fillIntakeClient(true);
// What is selected first is what the host would pin for an untouched start (it knows the defaults and what is installed).
Promise.all([fetch('work/client-default',{cache:'no-store'}).then(r=>r.json()),fetch('settings/status',{cache:'no-store'}).then(r=>r.json()).catch(()=>({})),fetch('settings/models').then(r=>r.json()).catch(()=>({}))]).then(([pinned,status,models])=>{intakeDefault=pinned.client||null;intakeDefaults=status.selection||null;intakeCatalogs=models;const select=document.getElementById('work-client');if(!intakeDefault&&!select.querySelector('option[value=""]'))select.insertAdjacentHTML('afterbegin','<option value="">'+esc(window.officeText('설정한 기본 앱'))+'</option>');if(!intakeTouched)select.value=intakeDefault?intakeDefault.id:'';fillIntakeClient(!intakeTouched);}).catch(()=>fillIntakeClient(!intakeTouched));
